input.newString:
 ctx.restore();
}
let mouseX=0,mouseY=0,mouseIn=false;
function worldShift(){let w=dimensions.w,h=dimensions.h;let center=Math.floor((cameraX+w*.48)/TILE);return h*.70-groundHeight(Math.max(0,Math.min(WORLD_W-1,center)))*TILE}
function coords(e){let r=canvas.getBoundingClientRect();mouseX=(e.clientX-r.left)*dimensions.w/r.width;mouseY=(e.clientY-r.top)*dimensions.h/r.height;mouseIn=true}
canvas.addEventListener('pointermove',coords);canvas.addEventListener('pointerleave',()=>mouseIn=false);
function mineOrPlace(screenX=mouseX,screenY=mouseY){let shift=worldShift();let tx=Math.floor((cameraX+screenX)/TILE),ty=Math.floor((screenY-shift)/TILE);if(tx<0||tx>=WORLD_W||ty<0||ty>=WORLD_H)return;let dist=Math.hypot(tx*TILE+16-player.x,ty*TILE+16-(player.y+16));if(dist>170){notify('Wander a little closer first!');return}let type=world[ty][tx];if(type){if(type==='leaf'||type==='wood'||type==='house'||type==='door'||type==='grass'||type==='dirt'||type==='stone'){world[ty][tx]=null;let yieldId=type==='leaf'||type==='wood'||type==='house'||type==='door'?'wood':type==='stone'?'stone':type==='dirt'?'dirt':'grass';addItem(yieldId);coins+=1;updateInventory();burst(tx*TILE+16,ty*TILE+14,['✦','·','✧'],'#fff1a8');notify(`Gathered ${items.find(i=>i.id===yieldId).name} +1`)}else notify('That bit is part of the cottage 🌼');return}
 let item=items[selected];if(!item||item.count<1){notify('You’re all out of that!');return}if(item.id==='seed'){let below=world[ty+1]?.[tx];if(below==='grass'||below==='dirt'){item.count--;flowers.push({x:tx,y:ty,grown:false,age:0});updateInventory();notify('A tiny seed is planted 🌱');return}else{notify('Seeds grow on soft earth');return}}
 if(!['grass','dirt','wood','stone'].includes(item.id)){notify('That item cannot be placed here');return}if(ty+1<WORLD_H&&world[ty+1][tx]&&!world[ty][tx]&&item.count){world[ty][tx]=item.id;item.count--;updateInventory();burst(tx*TILE+16,ty*TILE+16,['✦','✧'],'#dfffc2');notify(`${item.name} placed!`)}else notify('Place it above a solid block');}
function burst(x,y,texts,color){for(let i=0;i<5;i++)particles.push({x:x+(Math.random()-.5)*18,y:y+(Math.random()-.5)*12,text:texts[i%texts.length],color,age:0,life:650+Math.random()*350,size:10+Math.random()*8,vy:-.3-Math.random()*.7})}
canvas.addEventListener('pointerdown',e=>{coords(e);if(e.button===0)mineOrPlace()});
function doAction(){let shift=worldShift();let px=player.x+player.w/2-cameraX,py=player.y+player.h/2+shift;let gx=px+player.face*42;mouseX=gx;mouseY=py;mineOrPlace(gx,py)}
function jump(){if(player.ground){player.vy=-370;player.ground=false;burst(player.x+11,player.y+28,['·','✦'],'#fff')}}
function talk(msg){if(!msg.trim())return;chatLines.push({name:'SunnySprout',text:msg.trim()});if(chatLines.length>2)chatLines.shift();document.querySelectorAll('.chatline').forEach(e=>e.remove());let chat=document.getElementById('chat');for(const line of chatLines){let el=document.createElement('div');el.className='chatline';el.innerHTML=`<strong>${line.name}</strong> <span>${line.text.replace(/[<>]/g,'')}</span>`;chat.insertBefore(el,chat.querySelector('.chat-input'))}document.getElementById('chatInput').value='';notify('Message sent to Meadowbrook 💬')}
document.getElementById('sendChat').onclick=()=>talk(document.getElementById('chatInput').value);document.getElementById('chatInput').addEventListener('keydown',e=>{if(e.key==='Enter')talk(e.target.value);e.stopPropagation()});
function nearObject(){let n=npcs.find(a=>Math.abs(a.x-player.x)<90);if(n){notify(`${n.name}: Hey there, neighbor! 🌷`);burst(n.x+10,n.y,['♥','✧'],'#ffb5ad');return}let gx=Math.floor((player.x+player.w/2)/TILE);let gy=groundHeight(gx);if(Math.abs(gx-42)<5){notify('A cozy cottage... home sweet home 🏡');return}notify('The grove is full of little surprises ✨')}
document.querySelectorAll('[data-hold]').forEach(b=>{let k=b.dataset.hold;const down=e=>{e.preventDefault();keys[k]=true;b.classList.add('pressed')},up=e=>{e.preventDefault();keys[k]=false;b.classList.remove('pressed')};b.addEventListener('pointerdown',down);b.addEventListener('pointerup',up);b.addEventListener('pointercancel',up);b.addEventListener('pointerleave',up)});
document.querySelector('[data-tap="interact"]').addEventListener('pointerdown',e=>{e.preventDefault();doAction()});
window.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp',' ','ArrowDown'].includes(e.key))e.preventDefault();if(e.repeat)return;if(e.key==='a'||e.key==='ArrowLeft')keys.left=true;if(e.key==='d'||e.key==='ArrowRight')keys.right=true;if(e.key===' '||e.key==='w'||e.key==='ArrowUp')jump();if(e.key==='e'||e.key==='E')nearObject();if(e.key==='f'||e.key==='F')doAction();if(/^[1-4]$/.test(e.key)){selected=+e.key-1;updateInventory()}});
window.addEventListener('keyup',e=>{if(e.key==='a'||e.key==='ArrowLeft')keys.left=false;if(e.key==='d'||e.key==='ArrowRight')keys.right=false});window.addEventListener('blur',()=>{keys={}});
function showModal(title,copy,entries){document.getElementById('modalTitle').textContent=title;document.getElementById('modalCopy').textContent=copy;document.getElementById('modalItems').innerHTML=entries.map(e=>`<div class="modal-item" data-entry="${e.id}"><i>${e.icon}</i><b>${e.name}</b><small>×${e.count}</small></div>`).join('');document.getElementById('modalBackdrop').classList.add('open');document.querySelectorAll('.modal-item').forEach(el=>el.onclick=()=>{selected=Math.max(0,items.findIndex(i=>i.id===el.dataset.entry));updateInventory();closeModal();notify(`${items[selected].name} selected`)});}
function closeModal(){document.getElementById('modalBackdrop').classList.remove('open')}document.getElementById('closeModal').onclick=closeModal;document.getElementById('modalBackdrop').addEventListener('pointerdown',e=>{if(e.target.id==='modalBackdrop')closeModal()});document.getElementById('openBag').onclick=()=>showModal('Your backpack','Choose an item to add it to your quick slots.',items);document.getElementById('mobileBag').onclick=()=>showModal('Your backpack','Everything gathered on your little adventure.',items);
document.getElementById('craftBtn').onclick=()=>{if(items.find(i=>i.id==='seed').count>=2){items.find(i=>i.id==='seed').count-=2;items.find(i=>i.id==='grass').count+=1;updateInventory();notify('Crafted a meadow block! 🌱')}else notify('Collect 2 daisy seeds to craft a meadow block')};document.getElementById('sellBtn').onclick=()=>{let it=items[selected];if(it.count>0){it.count--;coins+=8;updateInventory();notify(`Traded ${it.name} for 8 dewdrops 🟡`)}else notify('Pick something to trade first')};
function navMessage(s){notify(s)}document.getElementById('questNav').onclick=()=>showModal('Daily delight','Gather blocks, plant flowers, and make your meadow bloom. Your next reward is 25 dewdrops!',items.slice(0,4));document.getElementById('mobileQuests').onclick=()=>document.getElementById('questNav').click();document.getElementById('friendsNav').onclick=()=>showModal('Your neighbors','A few friendly faces are exploring Meadowbrook today.',[{id:'friend1',icon:'🌷',name:'MossyMochi',count:'online'},{id:'friend2',icon:'🍄',name:'AcornAlex',count:'online'},{id:'friend3',icon:'🌿',name:'Pip',count:'online'}]);document.getElementById('shopNav').onclick=()=>showModal('Meadow market','A friendly trade stand — your dewdrops are ready to spend.',[{id:'seed',icon:'🌼',name:'Daisy seeds',count:'10 🟡'},{id:'wood',icon:'🪵',name:'Sunwood',count:'16 🟡'},{id:'stone',icon:'🪨',name:'Pebble',count:'12 🟡'}]);document.getElementById('mapNav').onclick=()=>navMessage('You’re at the heart of Meadowbrook 🗺️');document.getElementById('mobileMap').onclick=()=>navMessage('You’re at the heart of Meadowbrook 🗺️');document.getElementById('settingsBtn').onclick=()=>showModal('A little quiet time','Your progress is saved in this browser. Go on, make yourself at home!',[{id:'grass',icon:'🔊',name:'Sound',count:'On'},{id:'seed',icon:'🌤️',name:'Cozy mode',count:'On'}]);
function update(dt,t){let speed=180;player.vx=((keys.right?1:0)-(keys.left?1:0))*speed;if(player.vx)player.face=Math.sign(player.vx);player.x=Math.max(0,Math.min(WORLD_W*TILE-player.w,player.x+player.vx*dt));player.walk+=Math.abs(player.vx)*dt*.035;player.vy=Math.min(500,player.vy+900*dt);player.y+=player.vy*dt;let gy=floorY(player.x+player.w/2)-player.h;if(player.y>=gy){player.y=gy;player.vy=0;player.ground=true}else player.ground=false;
 for(const n of npcs){n.x+=n.vx*dt*38;if(n.x<6*TILE||n.x>WORLD_W*TILE-6*TILE)n.vx*=-1;n.face=Math.sign(n.vx||1);n.y=floorY(n.x+n.w/2)-n.h}
 for(const f of flowers){if(!f.grown){f.age+=dt;if(f.age>3){f.grown=true;burst(f.x*TILE+16,f.y*TILE+14,['✦','🌼'],'#fff5b4')}}}
 for(const p of particles){p.age+=dt*1000;p.y+=p.vy*dt*38}particles=particles.filter(p=>p.age<p.life);
 cameraX=Math.max(0,Math.min(WORLD_W*TILE-dimensions.w,player.x+player.w/2-dimensions.w*.47));}
function frame(t){let dt=Math.min(.04,(t-last)/1000||0);last=t;update(dt,t);drawWorld(t);requestAnimationFrame(frame)}
makeWorld();resize();updateInventory();
// restore a new player at a stable patch of ground
player.y=floorY(player.x+player.w/2)-player.h;npcs.forEach(n=>n.y=floorY(n.x+n.w/2)-n.h);
if('ontouchstart'in window)document.getElementById('hint').innerHTML='Tap a block to gather · Choose an item & tap to place';
requestAnimationFrame(frame);
})();
</script>
</body>
</html>

